"use strict";(globalThis.webpackChunkjc_community_site=globalThis.webpackChunkjc_community_site||[]).push([[18617],{3274(e,n,t){t.r(n),t.d(n,{assets:()=>h,contentTitle:()=>r,default:()=>c,frontMatter:()=>s,metadata:()=>i,toc:()=>d});const i=JSON.parse('{"id":"general/windows-mdm-lite-touch-deployment","title":"Windows Mdm Lite Touch Deployment","description":"By urvashi","source":"@site/docs/general/windows-mdm-lite-touch-deployment.md","sourceDirName":"general","slug":"/general/windows-mdm-lite-touch-deployment","permalink":"/jc-community-archive/general/windows-mdm-lite-touch-deployment","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Windows Mdm Lite Touch Deployment","description":"By urvashi"},"sidebar":"docs","previous":{"title":"Windows Mdm Enroll Devices Using Mdm Deep Link","permalink":"/jc-community-archive/general/windows-mdm-enroll-devices-using-mdm-deep-link"},"next":{"title":"Windows Policies Manage Zoom With A Boom","permalink":"/jc-community-archive/general/windows-policies-manage-zoom-with-a-boom-1886"}}');var o=t(74848),a=t(28453);const s={title:"Windows Mdm Lite Touch Deployment",description:"By urvashi"},r=void 0,h={},d=[{value:"Key Takeaways",id:"key-takeaways",level:3},{value:"Speaker",id:"speaker",level:3},{value:"Transcript",id:"transcript",level:3},{value:"Introduction and Problem Statement",id:"introduction-and-problem-statement",level:4},{value:"The Solution - Windows Lite Touch Deployment",id:"the-solution---windows-lite-touch-deployment",level:4},{value:"Creating the Provisioning Package",id:"creating-the-provisioning-package",level:4},{value:"Impact of Windows Lite Touch Deployment",id:"impact-of-windows-lite-touch-deployment",level:4},{value:"Phased Release Plan",id:"phased-release-plan",level:4},{value:"Deployment Strategies and Partnerships",id:"deployment-strategies-and-partnerships",level:4},{value:"Q&amp;A",id:"qa",level:4},{value:"Conclusion",id:"conclusion",level:4}];function l(e){const n={a:"a",h3:"h3",h4:"h4",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(n.p,{children:"This is an edited transcript of the 12.5.2024 IT Hour"}),"\n",(0,o.jsx)(n.h3,{id:"key-takeaways",children:"Key Takeaways"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["Hari Rawoola introduced ",(0,o.jsx)(n.strong,{children:"Windows Lite Touch Deployment, which aims to streamline the process of setting up new Windows devices for IT administrators."})]}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsx)(n.p,{children:"The primary issue addressed is the time-consuming nature of manually provisioning new Windows devices, which can significantly impact productivity and operational efficiency."}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsx)(n.p,{children:"The solution involves using a provisioning package (ppkg) created via the JumpCloud Admin Portal and Windows Configuration Designer tool. This package automates the setup of new devices, reducing setup time from hours to minutes."}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsx)(n.p,{children:"The provisioning package ensures security from the start of the device setup and includes an expiration mechanism (90 days or 500 device enrollments) to maintain control and prevent unauthorized use."}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsx)(n.p,{children:"The deployment of this new feature is planned in two phases. The first phase requires manual support team involvement for package revocation, while the second phase will introduce a UI in the Admin Portal to manage revocation."}),"\n"]}),"\n",(0,o.jsxs)(n.li,{children:["\n",(0,o.jsxs)(n.p,{children:["To learn more about this innovative deployment method and see it in action, check out the full ",(0,o.jsx)(n.a,{href:"https://www.youtube.com/watch?v=Xnw86TBNjAE&t=1673s",children:"video demonstration"})," for a comprehensive understanding of its capabilities and benefits."]}),"\n"]}),"\n"]}),"\n",(0,o.jsx)(n.h3,{id:"speaker",children:"Speaker"}),"\n",(0,o.jsx)(n.p,{children:"Hari Rawoola, Product Manager, JumpCloud"}),"\n",(0,o.jsx)(n.h3,{id:"transcript",children:"Transcript"}),"\n",(0,o.jsx)(n.h4,{id:"introduction-and-problem-statement",children:"Introduction and Problem Statement"}),"\n",(0,o.jsx)(n.p,{children:"I just want to introduce one of my friends who I met about a year ago at a bar. Meet John. He was a bit frustrated with a lot of stuff and then I got to know he is also an IT guy and he's frustrated for various reasons and one among that is his office stuff. Especially about getting the devices up and running, handing it over to the employees, and making work happen.\xa0"}),"\n",(0,o.jsx)(n.p,{children:"When we look at his typical day at work, right, a small portion of the work that he does at the office is to set up user accounts and then enroll the devices, assign them to the right groups, add some policies, configuration, make sure everything is going as per the use case. Every device is up and running. He just lives in the platform and makes sure everything is going smoothly by looking at insights. If there's a problem, he looks into it, troubleshoots it and gets a solution to that. This is his day-to-day activity. And when he was explaining his problem to me, he said, \u201cHey Hari, one of the problems I have is that I spend most of my time just enrolling devices, especially Windows devices.\u201d And that was one key takeaway from our discussion that day and we have been thinking about it."}),"\n",(0,o.jsx)(n.p,{children:"We have a great team here at JumpCloud and we have been thinking about what we can do? It's not just John's problem. It's IT\u2019s problem. So we wanted to solve this problem globally, not just make my friend John happy, but also the rest of the IT admins, so that we could automate a lot of this stuff. That's when we said, \u201cOkay, the problem admins have with provisioning new Windows devices, let's look at this problem.\u201d"}),"\n",(0,o.jsx)(n.p,{children:"So when we look at this problem of provisioning, each device may take several minutes to an hour. In this era, time is money and when there's no time, there's no money and we just cannot waste hours just configuring the device. Now if one device is going to take such a long period of time, imagine if there's a set of devices to be configured. That's going to be a nightmare, and we cannot just leave the problem out there and start focusing on the other things."}),"\n",(0,o.jsx)(n.p,{children:"So we just wanted to address this. Before provisioning the device, there are some manual configurations and that can be tedious and time-consuming too. Not only was my friend John spending much of his time configuring the device, but he was also spending time configuring other things before and after provisioning the device. That\u2019s tedious and time consuming. It delays getting devices to the users and thereby affects productivity which is a big, big concern to any organization.\xa0"}),"\n",(0,o.jsx)(n.p,{children:"It\u2019s not just that. It\u2019s directly proportional to security as well because we are all humans. John is human. Every IT admin is a human. So during this set of processes, there could be some inconsistency, or there could be some settings that could be configured incorrectly, and that could leave a device open to vulnerability. Anybody can get into the device and start playing around with the data.\xa0"}),"\n",(0,o.jsx)(n.h4,{id:"the-solution---windows-lite-touch-deployment",children:"The Solution - Windows Lite Touch Deployment"}),"\n",(0,o.jsx)(n.p,{children:"So bottom line, these are a set of problems that IT admins are facing today while provisioning new Windows devices, not just my friend John. So what are we trying to do now? We came up with a solution called Windows Lite Touch Deployment and for the tech-savvy who understand Windows jargon, it's a provisioning package, ppkg in short. So we came up with a pretty simplified solution for the admins out there.\xa0"}),"\n",(0,o.jsx)(n.p,{children:"So you guys just configure a source file which you can download from the Admin Portal, and you\u2019ll have to use an approved Microsoft third party tool to create and export a ppkg.\xa0"}),"\n",(0,o.jsx)(n.p,{children:"Now what is a provisioning package? It\u2019s a collection of settings. It could be as small as a peripheral setting like bluetooth all the way to certificate deployments to applications. Everything can be configured within this provisioning package in the tool called Windows Configuration Designer, which is a very user-friendly tool."}),"\n",(0,o.jsx)(n.p,{children:"All you have to do is import the source file that we provide in the Admin Portal and add the specific settings into that source file to create a provisioning package. Now this provisioning package just needs to be pushed to a flash drive and that\u2019s it. You could have one or many flash drives with this powerful provisioning package. It can live up to 90 days or for 500 device enrollments. We\u2019ll talk about why we have this validation but once you have this flash drive, all an IT Admin has to do is unbox a new device, power it on, and connect the USB stick. The Windows OS is very intelligent. \u201cOh there\u2019s a USB stick, I need to show some screens.\u201d And that\u2019s when it says, \u201cOh it\u2019s a provisioning package\u201d and everything is automated from there. Boom.\xa0"}),"\n",(0,o.jsx)(n.p,{children:"Now within this automation the admin can choose to create a local account with a certain username and passcode. Or it could automate a lot of stuff by connecting to Directory logins. So everything is automated. Now we\u2019re looking at bringing the time down from hours to minutes with this provisioning package. That\u2019s what we\u2019re providing. Now here\u2019s the flow.\xa0"}),"\n",(0,o.jsx)(n.h4,{id:"creating-the-provisioning-package",children:"Creating the Provisioning Package"}),"\n",(0,o.jsxs)(n.ol,{children:["\n",(0,o.jsx)(n.li,{children:"This needs to be done by the admin on a Windows 10 or 11 machine with Windows Configuration Designer installed. It\u2019s a small tool, so it\u2019s not rocket science but it is a prerequisite."}),"\n",(0,o.jsx)(n.li,{children:"Next, within the Admin Portal, in the devices section, you can download the source file"}),"\n",(0,o.jsx)(n.li,{children:"Open the source file in Windows Configuration Designer"}),"\n",(0,o.jsx)(n.li,{children:"Add all the settings you need to add. A ton of settings can be configured around accounts, bluetooth, location, certifications, apps, etc."}),"\n",(0,o.jsx)(n.li,{children:"Once you\u2019re done, export the provisioning package file and load it onto a flash drive"}),"\n"]}),"\n",(0,o.jsx)(n.p,{children:"Now this flash drive can be used to set up devices, which is nothing but the Out Of The Box Experience (OOBE). So what we\u2019re trying to do is bring the setup time down from an hour to two minutes. The whole process shouldn\u2019t take more than 15 minutes and that\u2019s the wow factor. When I discussed this process with my friend John he was pretty happy.\xa0"}),"\n",(0,o.jsx)(n.h4,{id:"impact-of-windows-lite-touch-deployment",children:"Impact of Windows Lite Touch Deployment"}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.strong,{children:"Security"})}),"\n",(0,o.jsx)(n.p,{children:"Let\u2019s go back to the expiration and validation I talked about. Why have we done that? Let\u2019s look at an example. Hari works at JumpCloud, he\u2019s an admin and he manages devices. He\u2019s got a flash drive with a provisioning package but it got into the hands of someone untrustworthy. That person could use that flash drive to set up devices. But this is proprietary to JumpCloud. So there is a validation and a revocation that can happen, which is a separate process. We\u2019ll have a ton of training material around that.\xa0"}),"\n",(0,o.jsx)(n.p,{children:"The most important thing is all the security settings can be configured right at runtime, which means the device is now being secured right from the starting point itself, not after the provisioning, enrolling, etc. It's being secured right from the starting point, and every organization would love that factor. Also there\u2019s no human error because there\u2019s no manual configuration for each device, meaning every device is equally secured."}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.strong,{children:"Scalability and ROI"})}),"\n",(0,o.jsx)(n.p,{children:"Next you can deploy a larger set of Windows endpoints quickly and easily. Like I said, time is money, and we are saving a ton of time and effort over here. This is going to improve the experience. Once the admin creates the provisioning package, they can use it for a pretty good duration of time and a pretty good number of devices without human intervention. It also means improved ROI with deployments going from an hour to two minutes. Which means larger deployments don\u2019t have to be nightmares.\xa0"}),"\n",(0,o.jsx)(n.h4,{id:"phased-release-plan",children:"Phased Release Plan"}),"\n",(0,o.jsx)(n.p,{children:"So when can IT admins like my friend John start using this? We have a release plan in two phases. Phase one goes live mid Jan so it\u2019ll be available for all IT Admins. In this phase, remember every provisioning package has a shelf life of 90 days or 500 device enrollments, whichever comes first, and after that the provisioning package won\u2019t be useful any more.\xa0"}),"\n",(0,o.jsx)(n.p,{children:"But how will an admin find out when that happens? In phase one they\u2019ll have to contact JumpCloud support. There will be some Directory Insights pertaining to that but they\u2019ll have to work with support to revoke the provisioning package or they can download a new configuration file and create a new ppkg which will then live on for another 90 days/500 devices.\xa0"}),"\n",(0,o.jsx)(n.p,{children:"In phase two, coming at the end of Q1 2024, IT Admins will have a UI where they can control revocation. So if it went into the wrong hands you can say \u201cLet me revoke the provisioning package from the Admin Portal\u201d.\xa0"}),"\n",(0,o.jsx)(n.h4,{id:"deployment-strategies-and-partnerships",children:"Deployment Strategies and Partnerships"}),"\n",(0,o.jsx)(n.p,{children:"Now let's talk about the deployment strategies."}),"\n",(0,o.jsxs)(n.ol,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Self Deployment"})," - An IT Admin can creates a provisioning package, have a set of flash drives, and start deploying devices. They can create as many ppkgs as they want and keep using them."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Work with your Vendor"})," - If you have a vendor who\u2019s creating images, you could create a provisioning package and give it to them to include in those images and give you zero touch deployment."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Reach out to JumpCloud\u2019s Warehousing Partners"})," - You could reach out to our warehousing partners, who can help you get the devices and everything set up. you just have to work with us, and we'll help you in reaching out to our warehouse partners."]}),"\n"]}),"\n",(0,o.jsx)(n.h4,{id:"qa",children:"Q&A"}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.strong,{children:"Q: How is JumpCloud\u2019s Windows Lite Touch Deployment different from the Windows Imaging and Configuration Designer Tool which has been around for a while?"})}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"A:"})," Well when you manage it from JumpCloud we provide some secret keys and tokens that are embedded into the provisioning package which our platform can identify. So it installs the agent and gets the MDM service running on the device. Once enrollment is done there\u2019s a set of policies that can be enforced and the device can be managed from JumpCloud.\xa0"]}),"\n",(0,o.jsx)(n.p,{children:"Other benefits would be the simplicity for less technical admins, no script to run and a clear UI on enrollment. Windows MDM enrollment shows clearly at the UIX for ppkg installation on the device. It\u2019s also where this fits into the broader onboarding story for a user to their JumpCloud managed Windows device. This paired with Self-Service Account Provisioning released in Q4 2023 makes the process even easier. It's a lite touch provisioning from an admin perspective and a zero-touch provisioning from the user perspective."}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.strong,{children:"Q: It does simplify the setup when we have access to the device before we provide it to a user. But we'd still require manual intervention when we drop ship a device to a work from home person."})}),"\n",(0,o.jsx)(n.p,{children:"**A:**In that case you could create the provisioning package and give it to the vendor, or a service provider to use. Or you could work with our various partners to automate that. There are a few cloud products as well. OSDCloud is one of them. It does involve some scripting and is technical but there is some nice documentation online. Essentially you can have the image built with the provisioning package so all the end user will have to do once they get the machine is to open it up and login and it\u2019ll be up and running.\xa0"}),"\n",(0,o.jsx)(n.h4,{id:"conclusion",children:"Conclusion"}),"\n",(0,o.jsx)(n.p,{children:"Microsoft can do whatever they want in the world of Windows. I wish we could do a lot more stuff but they own the operating system. We are just the subscribers. And they\u2019re not big on announcements. They have their insider programs and communities but they\u2019re looking to push features to Intune. We don\u2019t know their rules, we\u2019re just the subscribers.\xa0"}),"\n",(0,o.jsx)(n.p,{children:"Thank you all for joining and we\u2019ll see you next week."})]})}function c(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},28453(e,n,t){t.d(n,{R:()=>s,x:()=>r});var i=t(96540);const o={},a=i.createContext(o);function s(e){const n=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),i.createElement(a.Provider,{value:n},e.children)}}}]);